+      - {name: optionalInts, type: 'Optional<Map<Integer, Binary64>>'}
+  - {name: probe.float.Plain, kind: newtype, of: Integer}
+";
+
+fn plan() -> Plan {
+    Plan::from_model(&model::selection(SOURCE, &["probe.float.Envelope"]))
